 1739: function Get-ProseGate {
 1740:     param([string]$Text)
 1741:     $t = [string]$Text
 1742:     $words = @(($t -split '\s+') | Where-Object { $_ }).Count
 1743:     $numbered = $script:NumberedAnswerRe.Matches($t).Count
 1744:     $r = [pscustomobject]@{ Substantive = $false; Reason = ''; Words = $words; Numbered = $numbered }
 1745:     $head = ($t.Trim() -replace '[\u2018\u2019]', "'")
 1746:     if ($head.Length -gt 200) { $head = $head.Substring(0, 200) }
 1747:     $head = $head.ToLowerInvariant()
 1748:     $lead = $head -replace '^[\s*#>_`-]+', ''
 1749:     $startsRefusal = @($script:RefusalPhrases | Where-Object { $lead.StartsWith($_) }).Count -gt 0
 1750:     $hits = 0
 1751:     foreach ($ph in $script:RefusalPhrases) { $hits += ([regex]::Matches($head, [regex]::Escape($ph))).Count }
 1752:     $markers = ($numbered -gt 0) -or ($t -match '\bF[0-9]{2,}-[0-9]+\b') -or ($t -match '\bRC[0-9]+\b') -or ($t -match '(?i)\bverdict\b')
 1753:     if (($startsRefusal -or $hits -ge 2) -and -not $markers) { $r.Reason = 'reply looks like a refusal'; return $r }
 1754:     if (($numbered -ge 2 -and $words -ge 25) -or ($numbered -ge 1 -and $words -ge 40) -or $words -ge 120) { $r.Substantive = $true; return $r }
 1755:     $r.Reason = "reply too short ($words words)"
 1756:     return $r
 1757: }
