 1777: function ConvertTo-DriftText {
 1778:     param([string]$Text)
 1779:     return (([string]$Text -replace '\s+', ' ').Trim().ToLowerInvariant())
 1780: }
 1781: 
 1782: # What a format repair may have changed: the prose (the first reply) against the repaired
 1783: # object ($Reply: reply_markdown, findings, prior_findings, verdict). One note per check
 1784: # that differs, [string[]] (empty when clean):
 1785: #   1 the RC<n> ids of the prose vs of reply_markdown
 1786: #   2 the numbered answers (Q<n>. at a line start, bold or not) of both
 1787: #   3 every F<NN>-<k> id the prose names appears in prior_findings or findings
 1788: #   4 a verdict token the prose states (ACCEPT|HOLD|REJECT|ADVISE, after "Verdict" if
 1789: #     there is one) equals the JSON verdict
 1790: #   5 every prose sentence of >= 60 characters (whitespace-normalised; the 40 longest at
 1791: #     most, to bound the cost) appears in reply_markdown (normalised, case-insensitive) -
 1792: #     a changed remedy in a short sentence counts as much as one in a long one
 1793: function Get-FormatRepairDrift {
 1794:     param([string]$Prose, $Reply)
 1795:     $notes = New-Object System.Collections.Generic.List[string]
 1796:     $md = [string](Get-PropertyValue $Reply 'reply_markdown' '')
 1797:     $rcOf = { param($t) @([regex]::Matches([string]$t, '\bRC([0-9]+)\b') | ForEach-Object { [int]$_.Groups[1].Value } | Sort-Object -Unique | ForEach-Object { "RC$_" }) }
 1798:     $rcProse = @(& $rcOf $Prose)
 1799:     $rcMd = @(& $rcOf $md)
 1800:     if (($rcProse -join ',') -ne ($rcMd -join ',')) {
 1801:         $notes.Add("requested checks differ: prose $(if ($rcProse.Count) { $rcProse -join ', ' } else { 'none' }), reply_markdown $(if ($rcMd.Count) { $rcMd -join ', ' } else { 'none' })")
 1802:     }
 1803:     $qOf = { param($t) @([regex]::Matches([string]$t, '(?m)^\s*(?:\*\*)?Q([0-9]+)\.') | ForEach-Object { [int]$_.Groups[1].Value } | Sort-Object -Unique) }
 1804:     $qProse = @(& $qOf $Prose)
 1805:     $qMd = @(& $qOf $md)
 1806:     if ($qProse.Count -ne $qMd.Count) {
 1807:         $notes.Add("numbered answers differ: prose $($qProse.Count), reply_markdown $($qMd.Count)")
 1808:     }
 1809:     $idsProse = @([regex]::Matches([string]$Prose, '\bF[0-9]{2,}-[0-9]+\b') | ForEach-Object { $_.Value } | Sort-Object -Unique)
 1810:     if ($idsProse.Count -gt 0) {
 1811:         $known = New-Object System.Collections.Generic.List[string]
 1812:         foreach ($pf in @(Get-PropertyValue $Reply 'prior_findings' @())) { if ($pf) { $known.Add([string](Get-PropertyValue $pf 'id' '')) } }
 1813:         $findingsText = ConvertTo-Json -InputObject ([object[]]@(Get-PropertyValue $Reply 'findings' @())) -Depth 8 -Compress
 1814:         foreach ($m in [regex]::Matches([string]$findingsText, '\bF[0-9]{2,}-[0-9]+\b')) { $known.Add($m.Value) }
 1815:         $missing = @($idsProse | Where-Object { -not $known.Contains($_) })
 1816:         if ($missing.Count -gt 0) { $notes.Add("finding id(s) named in the prose but absent from prior_findings/findings: $($missing -join ', ')") }
 1817:     }
 1818:     $vm = [regex]::Match([string]$Prose, '\b[Vv]erdict\b[^A-Za-z]{0,12}(ACCEPT|HOLD|REJECT|ADVISE)\b')
 1819:     if (-not $vm.Success) { $vm = [regex]::Match([string]$Prose, '\b(ACCEPT|HOLD|REJECT|ADVISE)\b') }
 1820:     $jsonVerdict = [string](Get-PropertyValue $Reply 'verdict' '')
 1821:     if ($vm.Success -and $vm.Groups[1].Value -cne $jsonVerdict) {
 1822:         $notes.Add("verdict differs: prose $($vm.Groups[1].Value), JSON $(if ($jsonVerdict) { $jsonVerdict } else { '(none)' })")
 1823:     }
 1824:     $sentences = @(([string]$Prose -split '(?<=[.!?])\s+|\r?\n') | ForEach-Object { ConvertTo-DriftText $_ } | Where-Object { $_.Length -ge 60 } | Sort-Object -Unique | Sort-Object -Property Length -Descending | Select-Object -First 40)
 1825:     if ($sentences.Count -gt 0) {
 1826:         $mdNorm = ConvertTo-DriftText $md
 1827:         $lost = @($sentences | Where-Object { -not $mdNorm.Contains($_) })
 1828:         if ($lost.Count -gt 0) {
 1829:             $first = $lost[0]
 1830:             if ($first.Length -gt 60) { $first = $first.Substring(0, 60) + '...' }
 1831:             $notes.Add("$($lost.Count) of the $($sentences.Count) prose sentences (>= 60 chars) are not in reply_markdown (first: '$first')")
 1832:         }
 1833:     }
 1834:     return , ([string[]]$notes.ToArray())
 1835: }
== common provider classifier ==
 5740: # auth class would refuse that endpoint for 24 h although its credential is fine. Also "maximum
 5741: # context length is N tokens", context_length_exceeded, "exceeds the context window", "prompt is
 5742: # too long", "input token count ... exceeds the maximum number of tokens". A text that also names
 5743: # a usage limit stays quota - (wave 24c, F15-1) and so does one with ANY other quota-class wording
 5744: # (billing, payment, an insufficient balance, credits, a token plan: the complete quota pattern of
 5745: # $script:FailureClassPatterns): "billing_required: insufficient balance for this context window"
 5746: # is quota, never capability (Test-ContextOverflow).
 5747: $script:ContextOverflowPattern = '(?i)supports?\s+only\b.{0,80}?\b(?:context|tokens?)\b|context[ _-]?(?:length|window)|maximum\s+context|context_length_exceeded|prompt\s+is\s+too\s+long|input\s+(?:is\s+)?too\s+long|input\s+token\s+count|exceeds?\s+the\s+maximum\s+number\s+of\s+tokens'
 5748: $script:FailureClassPatterns = [ordered]@{
 5749:     'permission' = '(?i)no output produced|auto-denied|permission that headless mode'
 5750:     'capability' = '(?i)not supported|unsupported|does(?: not|n[''\u2019]t) support|do not support|feature_not_supported|json_schema|invalid_argument|invalid model selection|conflicts with --effort'
 5751:     'auth'       = '(?i)\b40[13]\b|unauthori[sz]ed|forbidden|invalid[ _]api[ _]key|\bauthentication\b|\bauth\b|\bapi key\b|permission_denied|unauthenticated|not signed in|login required|sign in to'
 5752:     'quota'      = '(?i)usage[ _]limit|quota|rate[ _]limit|\b429\b|insufficient balance|too many requests|credits? exhausted|credit balance|payment required|\b402\b|token plan|plan exhausted|billing|resource_exhausted|rate_limit_exceeded'
 5753:     'transport'  = '(?i)timeout|timed out|connection|econn|enotfound|\bdns\b|\btls\b|certificate|\b50[234]\b|network|\bunavailable\b|deadline_exceeded'
 5754: }
 5755: $script:BuiltinOpenAiFingerprint = Get-Sha256Hex ($script:Utf8NoBom.GetBytes('cc-provider-v1|builtin:openai'))
 5756: 
 5757: # permission | capability | auth | quota | transport | unknown
 5758: function Get-ProviderFailureClass {
 5759:     param([string]$Message)
 5760:     foreach ($k in $script:FailureClassPatterns.Keys) {
 5761:         if ($k -eq 'capability' -and (Test-ContextOverflow $Message)) { return 'capability' }
 5762:         if ($k -eq 'auth' -and $Message -match $script:QuotaTextPattern) { return 'quota' }
 5763:         if ($Message -match $script:FailureClassPatterns[$k]) { return $k }
 5764:     }
 5765:     return 'unknown'
 5766: }
 5767: 
 5768: # (wave 24b) The failure text says the prompt outgrew the context window of the plan or the model
 5769: # ($script:ContextOverflowPattern) and names no usage limit - (wave 24c, F15-1) no quota-class
 5770: # wording at all: the complete quota pattern (usage or rate limit, billing, payment, an
 5771: # insufficient balance, credits, a token plan, 402/429) wins over the context exception, so a
 5772: # quota or billing failure that also mentions a context window is never capability (no
 5773: # continuation after it, the endpoint out as for any quota).
 5774: function Test-ContextOverflow {
 5775:     param([string]$Message)
 5776:     return [bool]($Message -and $Message -match $script:ContextOverflowPattern -and $Message -notmatch $script:FailureClassPatterns['quota'])
 5777: }
 5778: 
 5779: # (wave 24b) The operator's next step for a recorded provider failure the bridge can explain - ''
 5780: # or one phrase. A context-window rejection (class capability, Test-ContextOverflow): "context too
 5781: # long for this plan/model - ...". The summary of a failed run prints it (`hint       :`), the
 5782: # handoff header after its `Provider failure:` line. (wave 24c, F15-4) The hint is decided when the
 5783: # failure is CLASSIFIED: New-ProviderFailure stores it as provider_failure.hint, from the code and
 5784: # the FULL message the class came from - a code-only context_length_exceeded ("Request too
 5785: # large."), a context phrase past the 200 characters the message keeps. Get-FailureHint reads it
 5786: # from there; an entry recorded before wave 24c has none: its class and its code + message decide.
 5787: $script:ContextHint = 'context too long for this plan/model - narrow the brief (fewer or smaller files to read, a smaller -Range, a reading plan) or choose a model with a larger context window'
 5788: function Get-ClassHint {
 5789:     param([string]$Class, [string]$Text)
 5790:     if ($Class -eq 'capability' -and (Test-ContextOverflow $Text)) { return $script:ContextHint }
 5791:     return ''
 5792: }
 5793: function Get-FailureHint {
 5794:     param($Failure)
 5795:     if ($null -eq $Failure) { return '' }
 5796:     $stored = Get-PropertyValue $Failure 'hint' $null
 5797:     if ($null -ne $stored) { return [string]$stored }
 5798:     $class = [string](Get-PropertyValue $Failure 'class' '')
 5799:     return (Get-ClassHint -Class $class -Text "$([string](Get-PropertyValue $Failure 'code' '')) $([string](Get-PropertyValue $Failure 'message' ''))")
 5800: }
 5801: 
 5802: # (wave 24c) A 429 that names no usage window and no quota is a BURST: ModelArk (BytePlus) answers
 5803: # "exceeded retry limit, last status: 429 Too Many Requests, request id: ..." for burst and
 5804: # concurrency limits that recover within minutes, besides the plan's own windows (live ledgers,
 5805: # 2026-09-26). provider_failure.kind 'burst' (after class; '' for every other failure): without a
 5806: # reset time such an endpoint is out for 10 minutes ($script:BurstOutMinutes), not 60. A 429 whose
 5807: # text names a usage limit, a quota, a balance, credits, billing, a token plan, an hour/day/week/
 5808: # month window or a reset keeps the 60-minute rule.
 5809: $script:BurstTextPattern = '(?i)\b429\b|too many requests|concurren'
 5810: $script:QuotaWindowPattern = '(?i)usage[ _]?limit|\bquota|resource_exhausted|insufficient|\bbalance|\bcredits?\b|\bbilling|\bpayment|\b402\b|token[ _]plan|plan exhausted|\b(?:hours?|days?|weeks?|months?)\b|hourly|daily|weekly|monthly|\bwindow|\bresets?\b'
 5811: $script:BurstOutMinutes = 10
 5812: $script:QuotaOutMinutes = 60
 5813: # 'burst' or '' - $Text: the code and the (full) message the class came from.
 5814: function Get-FailureKind {
 5815:     param([string]$Class, [string]$Text)
 5816:     if ($Class -ne 'quota' -or -not $Text) { return '' }
 5817:     if ($Text -match $script:BurstTextPattern -and $Text -notmatch $script:QuotaWindowPattern) { return 'burst' }
 5818:     return ''
 5819: }
 5820: 
 5821: # The provider's own error inside a failure text: an SSE payload `data:{"error":{...}}`
 5822: # (MiMo sends its rejections that way) or a bare `{"error":{...}}` -> error.message and
 5823: # error.code; otherwise the text itself. { Code; Message; Found (wave 24c: an error payload was
 5824: # found - structured evidence, Get-KilledTurnFailure) }.
 5825: function ConvertFrom-ProviderErrorText {
 5826:     param([string]$Text)
 5827:     $r = [pscustomobject]@{ Code = ''; Message = (ConvertTo-OneLine $Text); Found = $false }
 5828:     if (-not $Text) { return $r }
 5829:     $candidates = New-Object System.Collections.Generic.List[string]
 5830:     foreach ($m in [regex]::Matches($Text, '(?m)data:\s*(\{.*\})\s*$')) { $candidates.Add($m.Groups[1].Value) }
== common endpoint health ==
 6180: # Quota is used: Get-PlanQuotaVerdict); every record carries its Fingerprint.
 6181: # (wave 29b, E15) An entry that carries a quota mark - engine_run.quota_mark, the provider_failure a
 6182: # failed quota turn would have recorded, on a usable reply whose turn saw a rejecting rate-limit
 6183: # event - counts twice: as itself (a usable reply: RecentUsable, it clears older failures) and as that
 6184: # quota failure 1 ms after it, so the route stays out until the mark's reset (or 60 minutes, 10 for a
 6185: # burst) exactly as after a failed quota turn - and a later usable reply clears it as usual.
 6186: function Get-EndpointHealth {
 6187:     param([object[]]$Consults, [string]$Fingerprint, [datetime]$UtcNow = [datetime]::UtcNow, [switch]$NoMachine, [string[]]$Fingerprints = @())
 6188:     $h = [pscustomobject]@{ Auth = $null; Quota = $null; QuotaKnown = $false; LastLimit = $null; LastFailure = $null; RecentUsable = $null }
 6189:     $fpSet = @(@($Fingerprints) + @($Fingerprint) | Where-Object { $_ } | Select-Object -Unique)
 6190:     if ($fpSet.Count -eq 0) { return $h }
 6191:     $nowOffset = New-Object DateTimeOffset ([datetime]::SpecifyKind($UtcNow, [DateTimeKind]::Utc))
 6192:     $records = New-Object System.Collections.Generic.List[object]
 6193:     $allConsults = @($Consults | Where-Object { $null -ne $_ })
 6194:     if (-not $NoMachine) {
 6195:         foreach ($oneFp in $fpSet) {
 6196:             $machineEntries = ConvertTo-MachineHealthEntries -Fingerprint $oneFp
 6197:             $allConsults = @($allConsults) + @($machineEntries)
 6198:         }
 6199:     }
 6200:     # (E15) the quota marks as entries of their own, 1 ms after the entry that carries them
 6201:     $marked = New-Object System.Collections.Generic.List[object]
 6202:     foreach ($c in $allConsults) {
 6203:         $marked.Add($c)
 6204:         $qm = Get-PropertyValue (Get-PropertyValue $c 'engine_run' $null) 'quota_mark' $null
 6205:         if ($null -eq $qm -or [string](Get-PropertyValue $qm 'class' '') -ne 'quota') { continue }
 6206:         $mAt = ConvertTo-WhenOffset (Get-PropertyValue $c 'when' '')
 6207:         if ($null -eq $mAt) { continue }
 6208:         $mOrder = ConvertTo-WhenOffset (Get-PropertyValue $c 'finished_at' '')
 6209:         if ($null -eq $mOrder) {
 6210:             $mOrder = $mAt
 6211:             $mws = 0.0
 6212:             if ([double]::TryParse([string](Get-PropertyValue $c 'wall_seconds' ''), [System.Globalization.NumberStyles]::Float, $script:Invariant, [ref]$mws) -and $mws -gt 0) { $mOrder = $mAt.AddSeconds($mws) }
 6213:         }
 6214:         $marked.Add([pscustomobject]@{ n = (Get-PropertyValue $c 'n' 0); when = (Get-PropertyValue $c 'when' ''); finished_at = $mOrder.AddMilliseconds(1); bridge_outcome = 'failed: quota (a rate limit rejected a request during a usable turn)'; reviewer = (Get-PropertyValue $c 'reviewer' $null); provider_failure = $qm })
 6215:     }
 6216:     foreach ($c in $marked) {
 6217:         $rev = Get-PropertyValue $c 'reviewer' $null
 6218:         $fp = if ($null -eq $rev) { $script:BuiltinOpenAiFingerprint } else { [string](Get-PropertyValue $rev 'provider_fingerprint' '') }
 6219:         if (-not $fp -or $fpSet -notcontains $fp) { continue }
 6220:         $outcome = [string](Get-PropertyValue $c 'bridge_outcome' '')
 6221:         if (-not $outcome) { continue }
 6222:         $at = ConvertTo-WhenOffset (Get-PropertyValue $c 'when' '')
 6223:         if ($null -eq $at) { continue }
 6224:         # A failure stamped in the future (clock skew, a mislabelled zone) counts as now:
 6225:         # its age is clamped to 0, it is never skipped (F15-4).
 6226:         $age = [Math]::Max(0, ($UtcNow - $at.UtcDateTime).TotalMinutes)
 6227:         # "Newest" is by COMPLETION (D9, F03-3): a panel's members start together and finish in
 6228:         # any order, so a member that started later may have succeeded before an earlier one hit
 6229:         # its usage limit. finished_at (0.4.x wave 21), else when + wall_seconds (older entries),
 6230:         # else when; ties by n (F02-5).
 6231:         $order = ConvertTo-WhenOffset (Get-PropertyValue $c 'finished_at' '')
 6232:         if ($null -eq $order) {
 6233:             $order = $at
 6234:             $ws = 0.0
 6235:             if ([double]::TryParse([string](Get-PropertyValue $c 'wall_seconds' ''), [System.Globalization.NumberStyles]::Float, $script:Invariant, [ref]$ws) -and $ws -gt 0) { $order = $at.AddSeconds($ws) }
 6236:         }
 6237:         $entryN = 0
 6238:         [void][int]::TryParse([string](Get-PropertyValue $c 'n' ''), [ref]$entryN)
 6239:         $rec = [pscustomobject]@{ At = $at; Order = $order; N = $entryN; Ok = (Test-UsableOutcome $outcome); Class = ''; Code = ''; Message = ''; When = $at.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant); AgeMinutes = [int][Math]::Max(0, [Math]::Floor($age)); Age = $age; RetryAfter = $null; RetryAfterIso = ''; RetryAfterBasis = ''; Hit = $at; HitIso = ''; Until = $at.AddMinutes(60); FailureKind = ''; OutMinutes = $script:QuotaOutMinutes; Fingerprint = $fp }
 6240:         if (-not $rec.Ok) {
 6241:             $reference = $at
 6242:             $pf = Get-PropertyValue $c 'provider_failure' $null
 6243:             $recordedClass = ''
 6244:             if ($null -ne $pf) {
 6245:                 $rec.Class = [string](Get-PropertyValue $pf 'class' 'unknown')
 6246:                 $recordedClass = $rec.Class
 6247:                 # An entry recorded as auth whose message says usage limit / quota / rate limit
 6248:                 # counts as quota (Get-ProviderFailureClass's rule, applied when the ledger is
 6249:                 # READ): a 401/403 with a usage-limit text recorded before that rule existed
 6250:                 # (Kimi Code's 5-hour limit) stops refusing the endpoint for 24 h as an auth
 6251:                 # failure - without anyone editing the ledger.
 6252:                 if ($rec.Class -eq 'auth' -and ([string](Get-PropertyValue $pf 'message' '')) -match $script:QuotaTextPattern) { $rec.Class = 'quota' }
 6253:                 # (wave 24b) likewise a 401 whose text is a context-window limit of the plan
 6254:                 # (Test-ContextOverflow: Kimi Code's "Your current plan supports only k3 up to 256K
 6255:                 # context") counts as capability - it never refuses the endpoint for 24 h
 6256:                 elseif ($rec.Class -eq 'auth' -and (Test-ContextOverflow ([string](Get-PropertyValue $pf 'message' '')))) { $rec.Class = 'capability' }
 6257:                 # (wave 24c, F15-1) and an entry the context exception recorded as capability although
 6258:                 # its text also names a quota class (billing, a balance, credits - recorded before
 6259:                 # wave 24c) is read with today's classifier: quota wins
 6260:                 elseif ($rec.Class -eq 'capability' -and ([string](Get-PropertyValue $pf 'message' '')) -match $script:ContextOverflowPattern -and -not (Test-ContextOverflow ([string](Get-PropertyValue $pf 'message' '')))) {
 6261:                     $rec.Class = Get-ProviderFailureClass "$([string](Get-PropertyValue $pf 'code' '')) $([string](Get-PropertyValue $pf 'message' ''))"
 6262:                 }
 6263:                 $rec.Code = [string](Get-PropertyValue $pf 'code' '')
 6264:                 $rec.Message = [string](Get-PropertyValue $pf 'message' '')
 6265:                 # (wave 24c) the kind recorded with that class ('burst': a 429 that names no usage
 6266:                 # window or quota); an entry recorded before wave 24c, or read as another class, gets
 6267:                 # it from its code and message
 6268:                 $recordedKind = Get-PropertyValue $pf 'kind' $null
 6269:                 $rec.FailureKind = $(if ($null -ne $recordedKind -and $rec.Class -eq $recordedClass) { [string]$recordedKind } else { Get-FailureKind -Class $rec.Class -Text "$($rec.Code) $($rec.Message)" })
 6270:                 $pfWhen = ConvertTo-WhenOffset (Get-PropertyValue $pf 'when' '')
 6271:                 if ($null -ne $pfWhen) { $reference = $pfWhen }
 6272:                 $recorded = Get-PropertyValue $pf 'retry_after' $null
 6273:                 if ($null -ne $recorded -and "$recorded") { $rec.RetryAfter = ConvertTo-WhenOffset $recorded }
 6274:             } else {
 6275:                 # older entry: classify its bridge_outcome, lifting an SSE/JSON error payload
 6276:                 $parsedOutcome = ConvertFrom-ProviderErrorText -Text $outcome
 6277:                 $rec.Class = Get-ProviderFailureClass "$($parsedOutcome.Code) $outcome"
 6278:                 $rec.Code = $parsedOutcome.Code
 6279:                 $rec.Message = $parsedOutcome.Message
 6280:                 $rec.FailureKind = Get-FailureKind -Class $rec.Class -Text "$($rec.Code) $($rec.Message)"
 6281:             }
 6282:             if ($rec.Class -ne 'quota') { $rec.FailureKind = '' }
 6283:             $rec.OutMinutes = $(if ($rec.FailureKind -eq 'burst') { $script:BurstOutMinutes } else { $script:QuotaOutMinutes })
 6284:             # an entry recorded without retry_after: read the reset time from its message now
 6285:             if ($null -ne $rec.RetryAfter) { $rec.RetryAfterBasis = 'ledger' }
 6286:             else {
 6287:                 $rec.RetryAfter = Get-RetryAfter -Message $rec.Message -Reference $reference -ReferenceOffset
 6288:                 if ($null -ne $rec.RetryAfter) { $rec.RetryAfterBasis = 'message (reference offset)' }
